import{z as A,x as r,o as i,c as p,q as n,j as t,D as e,d as l,s as o,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"林达尔与萨缪尔森条件","description":"","frontmatter":{"title":"林达尔与萨缪尔森条件","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/lindahl-samuelson.md","filePath":"econ/lindahl-samuelson.md","lastUpdated":1791063341000}'),d={name:"econ/lindahl-samuelson.md"};function m(h,a,u,D,C,S){const B=r("Mermaid");return i(),p("div",null,[a[2]||(a[2]=n('<h1 id="林达尔与萨缪尔森条件" tabindex="-1">林达尔与萨缪尔森条件 <a class="header-anchor" href="#林达尔与萨缪尔森条件" aria-label="Permalink to &quot;林达尔与萨缪尔森条件&quot;">​</a></h1><div class="epigraph"><p>公共支出的最优规模，由所有人边际替代率之和等于边际转换率给出；林达尔份额则把这一加总拆成个性化价格。</p><footer>—— Samuelson, The Pure Theory of Public Expenditure, Review of Economics and Statistics, 1954；Lindahl, Just Taxation, 1919</footer></div><p><a href="/econ/common-pool">上一课</a>（公地悲剧）。已经写出纯公共品的标尺 \\(\\sum_i\\mathrm{MRS}^i=\\mathrm{MRT}\\)，以及自愿贡献只对齐私人 MRS。缺口是分权：计划者的切条件，能否像<a href="/econ/welfare-theorems">第二定理</a>那样用价格而不是数量指令去实现？林达尔均衡是公共品上的那组价格。本课钉这对偶，不重写免费搭车博弈。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>私人品的有效性是各人 MRS 分别等于 MRT，同一价格就够。公共品 \\(G\\) 同时进入每人的 \\(u^i\\)，资源约束是 \\(c(G)+\\sum x^i=w\\)。计划者在保留效用约束下取最优，一阶条件正是萨缪尔森加总——上一课当标尺用过，这里把它认作<strong>分权要去对准的对象</strong>。</p><p>Lindahl 价：每人面对自己的 \\(p^i\\)，生产者面对 \\(p=\\sum_i p^i=\\mathrm{MC}(G)\\)。消费者把 \\(G\\) 当私人品来买，但必须买同一数量。均衡时各人的需求 \\(G^i(p^i)\\) 重合为同一个 \\(G^*\\)，且 \\(p^i=\\mathrm{MRS}^i\\)。于是 \\(\\sum p^i=\\sum\\mathrm{MRS}^i=\\mathrm{MC}\\)，萨缪尔森条件被价格实现。</p><h3 id="林达尔不是统一税率" tabindex="-1">林达尔不是统一税率 <a class="header-anchor" href="#林达尔不是统一税率" aria-label="Permalink to &quot;林达尔不是统一税率&quot;">​</a></h3><p>统一税融资是「同一 \\(t\\)、同一 \\(G\\)」，一般对不齐各人 MRS。林达尔是对人报价：评价高的人 \\(p^i\\) 高。看起来像公正份额，执行却要知道偏好。上一课的自愿贡献失败，不能用「改成林达尔税表」自动救回——税表本身要真实 MRS。</p><p><span class="marginnote">几何：私人品需求横加（同一价格、数量相加）；公共品若要有效，应竖加（同一数量、价格相加）。林达尔价正是竖加的那一组纵轴截距。Samuelson 1955 的图把这条竖加画成社会边际收益。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：纯公共品、凸偏好、凸技术。结论：林达尔均衡配置是帕累托有效的；凸性下，任一有效配置可经总额转移成为林达尔均衡——第二定理的公共品版。存在性与瓦尔拉斯同类，价格向量换成 \\((p^1,\\ldots,p^n)\\) 且加总等于生产者价格。</p><p>显示问题单列：每人若被问「你的 MRS 是多少」，低报可压低 \\(p^i\\)、仍享受同一 \\(G\\)。林达尔作为机制不是激励相容的。Green–Laffont 等后来把这句话写成公共品显示的不可能；本课只钉价格对偶，不进入机制设计。</p>',12)),(i(),t(s,null,{default:e(()=>[o(B,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SAM%5B%22%E8%AE%A1%E5%88%92%E8%80%85%EF%BC%9A%CE%A3%20MRS%20%3D%20MRT%22%5D%20--%3E%20LIN%5B%22%E6%9E%97%E8%BE%BE%E5%B0%94%EF%BC%9A%E4%B8%AA%E6%80%A7%E5%8C%96%20p%5Ei%EF%BC%8C%CE%A3%20p%5Ei%20%3D%20MC%22%5D%0A%20%20LIN%20--%3E%20DEC%5B%22%E5%88%86%E6%9D%83%E5%AE%9E%E7%8E%B0%E7%AC%AC%E4%B8%80%E6%9C%80%E4%BD%B3%22%5D%0A%20%20LIN%20--%3E%20REV%5B%22%E6%89%A7%E8%A1%8C%E8%A6%81%E7%9C%9F%E5%AE%9E%20MRS%22%5D%0A%20%20VOL%5B%22%E8%87%AA%E6%84%BF%E8%B4%A1%E7%8C%AE%EF%BC%9A%E5%8F%AA%E5%AF%B9%E9%BD%90%E7%A7%81%E4%BA%BA%20MRS%22%5D%20--%3E%20FAIL%5B%22%E5%88%B0%E4%B8%8D%E4%BA%86%E8%90%A8%E7%BC%AA%E5%B0%94%E6%A3%AE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"为什么必须竖着加：一单位 \\(G\\) 同时服务所有人，社会边际收益是各人边际评价相加，不是「找一个代表消费者的 MRS」。私人品市场把横比做成同一价格；公共品没有「每人一份」，除非人为拆开价格。林达尔就是那次拆开。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：公共品像一盏路灯——同一盏灯照所有人，社会值多少要把每个人愿意出的钱竖着叠起来；私人品像一屉包子，你多吃一个别人就少吃一个，市场只需数总量、定统一价。竖加与横加的区别，根源就在「同一份能不能同时给两个人用」。")],-1)),a[6]||(a[6]=E("p",null,"总额转移仍必要。林达尔均衡相对于初始禀赋，可能有效但不公平；要到达指定的有效点，先改购买力，再开个性化价——与第二定理同一结构，只是价格按人而不是按商品分叉。",-1)),(i(),t(s,null,{default:e(()=>[o(B,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E4%B8%80%E5%8D%95%E4%BD%8D%E5%85%AC%E5%85%B1%E5%93%81%20G%22%5D%20--%3E%20SHARE%5B%22%E5%90%8C%E4%B8%80%E4%BB%BD%E5%90%8C%E6%97%B6%E6%9C%8D%E5%8A%A1%E6%89%80%E6%9C%89%E4%BA%BA%22%5D%0A%20%20SHARE%20--%3E%20VERT%5B%22%E7%A4%BE%E4%BC%9A%E8%BE%B9%E9%99%85%E6%94%B6%E7%9B%8A%20%3D%20%E5%90%84%E4%BA%BA%E8%AF%84%E4%BB%B7%E7%AB%96%E7%9D%80%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20VERT%20--%3E%20LIND%5B%22%E6%9E%97%E8%BE%BE%E5%B0%94%3A%20%E6%AF%8F%E4%BA%BA%E4%B8%80%E4%B8%AA%E4%BB%B7%2C%20%E5%8A%A0%E6%80%BB%E7%AD%89%E4%BA%8E%20MC%22%5D%0A%20%20X%5B%22%E4%B8%80%E5%8D%95%E4%BD%8D%E7%A7%81%E4%BA%BA%E5%93%81%22%5D%20--%3E%20RIVAL%5B%22%E5%8F%AA%E8%83%BD%E7%BB%99%E4%B8%80%E4%B8%AA%E4%BA%BA%E6%B6%88%E8%B4%B9%22%5D%0A%20%20RIVAL%20--%3E%20HOR%5B%22%E5%B8%82%E5%9C%BA%E9%9C%80%E6%B1%82%20%3D%20%E5%90%84%E6%95%B0%E9%87%8F%E6%A8%AA%E7%9D%80%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20HOR%20--%3E%20MKT%5B%22%E7%BB%9F%E4%B8%80%E4%BB%B7%E6%A0%BC%E5%8D%B3%E5%8F%AF%E5%87%BA%E6%B8%85%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p>个性化价格加总必须等于生产者价格，否则公共品生产的收支对不上。这是预算平衡，不是又一条偏好假设。谎报会同时弄乱加总与需求重合，林达尔作为机制从两边一起垮。</p><p><span class="marginnote">数字实例：路灯对甲值 6 元、对乙值 4 元，边际成本 10 元——萨缪尔森条件 \\(6+4=10\\) 成立，该装。若统一收税每人 5 元，乙因 \\(4 \\lt 5\\) 而反对；林达尔让甲付 6、乙付 4 恰好落地，但乙有动机谎称自己只值 0——效率条件对，执行激励错。</span></p><h3 id="标尺、分权、机制是三句话" tabindex="-1">标尺、分权、机制是三句话 <a class="header-anchor" href="#标尺、分权、机制是三句话" aria-label="Permalink to &quot;标尺、分权、机制是三句话&quot;">​</a></h3><p>萨缪尔森条件是完全信息计划者的切条件。林达尔是它的价格翻译。自愿贡献、投票、统一税是另一些机制，一般到不了切条件。上一课把机制失败讲完；本课把「失败相对什么」钉成可分权的第一最佳。后课用税融资时，统一楔子会再改写这条切条件，那是次优，不是把萨缪尔森作废。</p><p><span class="marginnote">Bowen–Lindahl–Samuelson 有时用来称呼同一加总条件。Bowen 从投票中位谈公共支出；Lindahl 从份额；Samuelson 从帕累托规划。本课用后两者的对偶，不引入中位选民。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>非凸、拥挤、地方公共品，加总条件要改：拥挤使 \\(G\\) 部分竞争，有效性加拥挤的边际损害。Tiebout 用脚投票是另一套分权，不在本课。林达尔价也不是可操作税制：税务局看不见 MRS。统一税加公共提供可以逼近某个 \\(G\\)，但对不齐各人 \\(p^i\\)，一般不是林达尔均衡。</p><p>存在性与瓦尔拉斯平行：价格单纯形换成「份额单纯形」\\(\\sum_i p^i=p\\)，超额需求是各人想要的 \\(G\\) 之差。凸性保证不动点；非凸（门槛、不可分项目）可以没有林达尔均衡，计划者仍可能有萨缪尔森意义上的最优数量——分权失败不等于切条件没定义。</p><p>后课默认：纯公共品第一最佳由萨缪尔森条件刻画，林达尔价是其分权；自愿供给与统一税都不是这组价格。激励相容另说。</p><p><span class="marginnote">常见误区：初学者容易把林达尔份额读成「公平分摊」——其实它只负责把效率翻译成价格，各人 \\(p^i\\) 可以非常悬殊，且依赖初始禀赋；要谈公平，得先用总额转移改购买力，再开个性化价，两件事不能混为一谈。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>萨缪尔森条件是计划者切条件：MRS 之和等于 MRT。</li><li>林达尔用个性化价格分权实现同一条件，对应公共品版第二定理。</li><li>竖加总，不是私人品的横加总。</li><li>作为机制，林达尔要真实偏好，谎报有利。</li><li>出处：Lindahl, 1919；Samuelson, <em>REStat</em>, 1954、1955。</li></ul>',12))])}const R=A(d,[["render",m]]);export{f as __pageData,R as default};
